package dev.soundceiling.app;
import android.content.*;import android.net.Uri;import android.os.*;import android.provider.MediaStore;import java.io.*;import java.nio.charset.StandardCharsets;import java.text.SimpleDateFormat;import java.util.*;
final class SessionLogger implements AutoCloseable{private final Context context;private final String id;private OutputStream out;private Uri uri;private int part=1;private long bytes;private SessionLogger(Context c)throws IOException{context=c.getApplicationContext();id=new SimpleDateFormat("yyyyMMdd-HHmmss",Locale.US).format(new Date());open();}static SessionLogger start(Context c,String header)throws IOException{SessionLogger l=new SessionLogger(c);l.write(header);return l;}synchronized void decision(ControlDecision d){write(LogFormatter.formatDecision(d));}synchronized void event(String c,String d){write(LogFormatter.formatEvent(SystemClock.elapsedRealtime(),c,d));}String status(){return uri==null?"":uri.toString();}private void open()throws IOException{ContentValues v=new ContentValues();v.put(MediaStore.Downloads.DISPLAY_NAME,LogFilePolicy.partName(id,part));v.put(MediaStore.Downloads.MIME_TYPE,"text/plain");v.put(MediaStore.Downloads.RELATIVE_PATH,Environment.DIRECTORY_DOWNLOADS+"/SoundCeiling/Logs/");uri=context.getContentResolver().insert(MediaStore.Downloads.EXTERNAL_CONTENT_URI,v);if(uri==null)throw new IOException("MediaStore insert failed");out=context.getContentResolver().openOutputStream(uri,"w");if(out==null)throw new IOException("openOutputStream failed");Prefs.get(context).edit().putString(Prefs.LAST_LOG_URI,uri.toString()).apply();bytes=0;}private void write(String line){try{byte[] b=(line+"\n").getBytes(StandardCharsets.UTF_8);if(bytes+b.length>LogFilePolicy.MAX_BYTES){out.close();part++;open();}out.write(b);out.flush();bytes+=b.length;}catch(IOException ignored){}}public synchronized void close(){try{if(out!=null)out.close();}catch(IOException ignored){}out=null;}}
